recipes.code:
{
  "inputs": [
    {
      "id": "gainium-api-key",
      "type": "promptString",
      "description": "Gainium API key (https://app.gainium.io → Settings → API)",
      "password": true
    },
    {
      "id": "gainium-api-secret",
      "type": "promptString",
      "description": "Gainium API secret (paired with GAINIUM_API_KEY)",
      "password": true
    }
  ],
  "servers": {
    "gainium": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "gainium-mcp@3.3.0"
      ],
      "env": {
        "GAINIUM_API_KEY": "${input:gainium-api-key}",
        "GAINIUM_API_SECRET": "${input:gainium-api-secret}",
        "GAINIUM_PAPER_ONLY": "false",
        "GAINIUM_ALLOWED_BOT_ID": "<gainium-allowed-bot-id>"
      }
    }
  }
}
